def get_ref_path(filename):
    """Get path to MATLAB reference file."""
    test_dir = Path(__file__).parent
    ref_dir = test_dir.parent.parent / "fastLPR" / "tests" / "refs" / "crosslang_unit"
    return ref_dir / filename


def load_nufft_ref(filename):
    """Load MATLAB reference data for NUFFT tests."""
    ref_path = get_ref_path(filename)
    if not ref_path.exists():
        pytest.skip(f"Reference file not found: {ref_path}")

    mat = loadmat(str(ref_path), squeeze_me=True, struct_as_record=False)
    return mat


def compute_naive_dft_1d(x, y, N):
    """Compute naive DFT for 1D as reference.

    Formula: (1/M) * sum(y * exp(-i*2*pi*k*x))
    Matches NUFFT(isdeconv=False) with ~0.12 error (spreading approximation).
    """
    M = len(x)
    x_flat = np.ravel(x)
    y_flat = np.ravel(y)
    k = np.arange(-N//2, N - N//2)
    naive = np.zeros(N, dtype=complex)
    for ik, kval in enumerate(k):
        phase = -2 * np.pi * kval * x_flat
        naive[ik] = np.sum(y_flat * np.exp(1j * phase)) / M
    return naive


def compare_results(py_result, ref_result):
    """Compute comparison metrics between Python and reference results."""
    py_vec = np.ravel(py_result)
    ref_vec = np.ravel(ref_result)

    # Handle complex arrays
    if np.iscomplexobj(py_vec) or np.iscomplexobj(ref_vec):
        py_vec = np.asarray(py_vec, dtype=complex)
        ref_vec = np.asarray(ref_vec, dtype=complex)

    abs_err = np.abs(py_vec - ref_vec)
    max_abs_err = np.max(abs_err)
    mean_abs_err = np.mean(abs_err)

    # Compute relative error with safe denominator
    denom = np.maximum(np.abs(ref_vec), 1e-10)
    rel_err = abs_err / denom
    significant_mask = np.abs(ref_vec) > 1e-10
    max_rel_err = np.max(rel_err[significant_mask]) if np.any(significant_mask) else 0.0

    return {
        'max_abs_err': float(max_abs_err),
        'mean_abs_err': float(mean_abs_err),
        'max_rel_err': float(max_rel_err)
    }


