# =============================================================================

class TestNUFFTSelfConsistency:
    """Self-consistency tests that don't need external reference."""

    def test_constant_y_1d(self):
        """UNIT: nufftn_type1 with constant y produces expected spectrum"""
        np.random.seed(RANDOM_SEED)
        M = 100
        N = 32

        x = np.random.rand(M, 1)
        y = np.ones((M, 1)) * 5.0  # Constant value

        # Shift x to [-0.5, 0.5] for proper centering
        x_centered = x - 0.5
        df = np.array([1.0 / N])

        result = nufftn_type1(x_centered, y, df=df, iflag=-1, acc=9, isdeconv=True)

        # For constant y, DC component should dominate
        # Find index of DC component (should be near center after fftshift-like arrangement)
        dc_idx = N // 2
        dc_power = np.abs(result[dc_idx, 0])
        total_power = np.sum(np.abs(result))

        # DC should be significant portion of total power
        assert dc_power > 0.5 * total_power / N, \
            f"DC power {dc_power:.2e} should be significant"

    # test_symmetric_y_1d - ARCHIVED (similar to test_constant_y_1d)
    # test_linearity_1d - ARCHIVED (keep only accuracy test)

    def test_accuracy_improves_with_parameter(self):
        """UNIT: Higher accuracy parameter should not degrade results"""
        np.random.seed(RANDOM_SEED)
        M = 50
        N = 16

        x = np.random.rand(M, 1) - 0.5
        y = np.sin(2 * np.pi * x) + 0.1 * np.random.randn(M, 1)
        df = np.array([1.0 / N])

        # Run with increasing accuracy
        results = {}
        for acc in [4, 6, 9, 12]:
            results[acc] = nufftn_type1(x, y, df=df, iflag=-1, acc=acc, isdeconv=True)

        # Higher accuracy should converge (results should stabilize)
        # Compare acc=9 vs acc=12 - should be very close
        diff_9_12 = compare_results(results[9], results[12])

        # They should be very close (both are high accuracy)
        assert diff_9_12['max_abs_err'] < 1e-6, \
            f"acc=9 vs acc=12 difference={diff_9_12['max_abs_err']:.2e} should be < 1e-6"

    def test_reproducible_results(self):
        """UNIT: nufftn_type1 produces reproducible results"""
        np.random.seed(RANDOM_SEED)
        M = 50
        N = 20

        x = np.random.rand(M, 1)
        y = np.sin(2 * np.pi * x)
        df = np.array([1.0 / N])

        result1 = nufftn_type1(x, y, df=df, iflag=-1, acc=9, isdeconv=True)
        result2 = nufftn_type1(x, y, df=df, iflag=-1, acc=9, isdeconv=True)

        # Same inputs should give identical outputs
        np.testing.assert_array_equal(result1, result2,
            err_msg="Results should be reproducible")


