class TestNUFFTEdgeCases:
    """Edge case tests for robustness."""

    def test_single_point_1d(self):
        """UNIT: nufftn_type1 handles M=1 (single point)"""
        x = np.array([[0.0]])
        y = np.array([[1.0]])
        N = 8
        df = np.array([1.0 / N])

        result = nufftn_type1(x, y, df=df, iflag=-1, acc=6, isdeconv=True)

        # Should return valid result
        assert result.shape[0] == N
        assert not np.any(np.isnan(result))
        assert not np.any(np.isinf(result))

    def test_two_points_1d(self):
        """UNIT: nufftn_type1 handles M=2 (two points)"""
        x = np.array([[0.1], [0.9]])
        y = np.array([[1.0], [2.0]])
        N = 8
        df = np.array([1.0 / N])

        # Shift to center
        x_centered = x - 0.5

        result = nufftn_type1(x_centered, y, df=df, iflag=-1, acc=6, isdeconv=True)

        assert result.shape[0] == N
        assert not np.any(np.isnan(result))
        assert not np.any(np.isinf(result))

    # test_large_n_1d - ARCHIVED: 2026-01-10 (not in R reference)
    # See: dev/archive/tests-archive-20260110/python/unit/archived_test_nufft_extra.py

    def test_boundary_x_1d(self):
        """UNIT: nufftn_type1 handles x values at boundaries"""
        # x values at exact boundaries [-0.5, 0.5]
        x = np.array([[-0.5], [-0.25], [0.0], [0.25], [0.49999]])
        y = np.array([[1.0], [2.0], [3.0], [2.0], [1.0]])
        N = 8
        df = np.array([1.0 / N])

        result = nufftn_type1(x, y, df=df, iflag=-1, acc=6, isdeconv=True)

        assert result.shape[0] == N
        assert not np.any(np.isnan(result))
        assert not np.any(np.isinf(result))

