class TestNUFFTIsdeconv:
    """Tests for isdeconv parameter."""

    # test_isdeconv_false - ARCHIVED: 2026-01-10 (not in R reference)
    # See: dev/archive/tests-archive-20260110/python/unit/archived_test_nufft_extra.py

    def test_nufft_vs_naive_dft_1d(self):
        """UNIT: NUFFT(isdeconv=False) matches naive DFT within tolerance.

        Note: Spreading kernel introduces ~0.12 error at acc=12.
        """
        np.random.seed(RANDOM_SEED)
        M = 100
        N = 32

        x = np.random.rand(M, 1) - 0.5  # [-0.5, 0.5]
        y = np.sin(2 * np.pi * x)
        df = np.array([1.0 / N])

        # NUFFT without deconvolution
        result = nufftn_type1(x, y, df=df, iflag=-1, acc=12, isdeconv=False)

        # Naive DFT
        naive = compute_naive_dft_1d(x, y, N)

        # Compare (tolerance 0.15 for spreading approximation)
        max_err = np.max(np.abs(np.ravel(result) - naive))
        assert max_err < 0.15, \
            f"NUFFT vs naive DFT: max_err={max_err:.2e} should be < 0.15"

    # test_isdeconv_difference - ARCHIVED (redundant with test_isdeconv_false)
    # See: dev/archive/py-nufft-tests-20260109/archived_nufft_tests.py


